begin;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Certidão predial: o que realmente diz» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "REN — REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "O que é", "body": "A Certidão Permanente do Registo Predial é uma consulta eletrónica que permite aceder aos registos em vigor e aos pedidos de registo pendentes relativos a um prédio descrito."}, {"title": "Como se lê", "body": "Comece pela identificação/descrição do prédio; depois leia inscrições de aquisição e titulares; em seguida procure ónus e encargos; finalmente verifique averbamentos, cancelamentos e apresentações pendentes."}, {"title": "O que pode encontrar", "body": "Aquisição, compropriedade, usufruto, hipoteca, penhora, servidão e outros factos sujeitos a registo, dependendo do prédio."}, {"title": "O que não prova", "body": "Não prova, por si só, licenciamento, correspondência integral da realidade física, área útil ou regularidade urbanística."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Certidão predial: o que realmente diz», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Certidão predial: o que realmente diz» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://justica.gov.pt/Servicos/Balcao-Casa-Pronta', verified_at=date '2026-08-20' where id=122;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Caderneta predial: função fiscal e validade» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "REN — REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "O que é", "body": "A Caderneta Predial é um documento matricial/fiscal emitido no âmbito da Autoridade Tributária. Identifica o prédio para efeitos fiscais e reúne elementos matriciais."}, {"title": "Artigo matricial", "body": "É o número atribuído ao prédio na matriz fiscal. Não é o mesmo que o número da descrição no Registo Predial."}, {"title": "Titular matricial", "body": "É a pessoa ou entidade associada fiscalmente ao prédio. Deve ser confrontada com a titularidade registral quando a propriedade é relevante."}, {"title": "Afetação", "body": "É a utilização/afetação considerada na matriz para efeitos fiscais. Não deve ser transformada automaticamente numa conclusão sobre o uso urbanisticamente autorizado."}, {"title": "Ano de inscrição na matriz", "body": "É o ano em que o prédio foi inscrito na matriz. Não permite, isoladamente, concluir que esse é o ano de construção."}, {"title": "VPT — Valor Patrimonial Tributário", "body": "VPT significa Valor Patrimonial Tributário: valor fiscal atribuído ao prédio segundo as regras do CIMI. Não é, por definição, o valor de mercado."}, {"title": "Áreas", "body": "Leia sempre o nome exato do campo. Área total do terreno, implantação, área bruta privativa, área bruta dependente e outras métricas não são sinónimos entre si nem equivalem automaticamente a área útil/habitável."}, {"title": "Limite da caderneta", "body": "A matriz tem função fiscal. Não prova, por si só, que uma construção ou ampliação esteja urbanisticamente regular."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Caderneta predial: função fiscal e validade», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Caderneta predial: função fiscal e validade» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://justica.gov.pt/Servicos/Balcao-Casa-Pronta', verified_at=date '2026-08-20' where id=123;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Cruzamento documental profissional» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "REN — REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "RAN", "body": "RAN significa Reserva Agrícola Nacional: regime de proteção de solos com aptidão agrícola, sujeito a regras próprias."}, {"title": "REN", "body": "REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "Como analisar", "body": "Primeiro confirmar incidência cartográfica; depois identificar a operação pretendida; só então consultar o regime aplicável e eventuais procedimentos/compatibilidades."}, {"title": "Erro frequente", "body": "“Está em RAN/REN, logo é impossível” e “há casas ao lado, logo pode construir” são conclusões simplistas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Cruzamento documental profissional», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Cruzamento documental profissional» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://justica.gov.pt/Servicos/Balcao-Casa-Pronta', verified_at=date '2026-08-20' where id=124;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Checklist de apartamento» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O conceito central", "body": "«Checklist de apartamento» deve ser entendido no contexto do módulo «Apartamento / Fração Autónoma». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Checklist de apartamento», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Checklist de apartamento» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://justica.gov.pt/Servicos/Balcao-Casa-Pronta', verified_at=date '2026-08-20' where id=125;
