update public.lessons set content='{"intro": "Nesta aula vai aprender «Exceções e validade» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O que é o certificado energético", "body": "Documento emitido no âmbito do SCE que caracteriza o desempenho energético do edifício ou fração abrangida."}, {"title": "O que deve ler", "body": "Identificação do imóvel, classe energética, validade, técnico emissor e recomendações/informação constante do documento."}, {"title": "Pré-certificado", "body": "Documento aplicável em determinadas fases de projeto/construção, distinto do certificado final."}, {"title": "Publicidade", "body": "Quando o regime exige certificado, a publicidade deve refletir corretamente a classe energética."}, {"title": "Exceções", "body": "Existem exclusões e situações próprias; devem ser confirmadas no regime vigente e no SCE."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Exceções e validade», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Exceções e validade» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://justica.gov.pt/Servicos/Balcao-Casa-Pronta', verified_at=date '2026-08-20' where id=151;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Dossier antes do CPCV» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "CPCV — CPCV significa Contrato-Promessa de Compra e Venda: contrato através do qual as partes se comprometem a celebrar posteriormente a compra e venda, nas condições que nele acordarem."}, {"title": "O que é o CPCV", "body": "CPCV significa Contrato-Promessa de Compra e Venda: contrato através do qual as partes se comprometem a celebrar posteriormente a compra e venda, nas condições que nele acordarem."}, {"title": "Partes e imóvel", "body": "O contrato deve identificar corretamente as partes e o imóvel/objeto prometido."}, {"title": "Preço e pagamentos", "body": "Deve tornar claro o preço e o regime dos montantes entregues, incluindo quando assumem natureza de sinal."}, {"title": "Prazos e condições", "body": "Prazo para o ato definitivo, condições, documentação e eventuais dependências como financiamento devem ser redigidos e validados adequadamente."}, {"title": "Papel do consultor", "body": "Organizar factos, transmitir informação e assegurar que questões relevantes são encaminhadas para validação jurídica; não improvisar cláusulas jurídicas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Dossier antes do CPCV», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Dossier antes do CPCV» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://justica.gov.pt/Servicos/Balcao-Casa-Pronta', verified_at=date '2026-08-20' where id=152;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Preferências públicas» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O conceito central", "body": "«Preferências públicas» deve ser entendido no contexto do módulo «Venda — preparação do negócio». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Preferências públicas», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Preferências públicas» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://justica.gov.pt/Servicos/Balcao-Casa-Pronta', verified_at=date '2026-08-20' where id=153;
